-- deprecated: False
-- sha256: 55f609ad1af247afe23584a4c8f7c753b353b0cb4405351e41bd1255eee82f92
CREATE TEMPORARY VIEW dim_search_guide_${grass_region_without_quote} AS
SELECT
    user_id
    ,global_session_id
    ,CASE
          WHEN page_type = 'pre_search' AND page_section[0] = 'search_bar' AND target_type = 'search_prefill' AND prefill_type = 'auto' THEN 'sdp_algo_prefill'
          WHEN page_type = 'pre_search' AND page_section[0] = 'search_bar' AND target_type = 'hint_keyword' AND input_type = 'auto' THEN 'sdp_algo_prefill'
          WHEN page_type = 'pre_search' AND page_section[0] = 'search_bar' AND target_type = 'search_prefill' AND prefill_type = 'config' THEN 'sdp_ops_prefill'
          WHEN page_type = 'pre_search' AND page_section[0] = 'search_bar' AND target_type = 'hint_keyword' AND input_type = 'config' THEN 'sdp_ops_prefill'
          WHEN page_type = 'pre_search' AND page_section[0] = 'search_bar' AND target_type = 'hint_keyword' AND input_type in ('hashtag_history', 'history', 'shop_history', 'hint', 'shop')  THEN 'sdp_hint_history'
          WHEN page_type = 'pre_search' AND page_section[0] = 'search_history' AND target_type = 'keyword' THEN 'sdp_hint_history'
          WHEN page_type = 'pre_search' AND page_section[0] in ('popular_searches', 'search_suggestions') AND target_type = 'keyword' THEN 'sdp_search_suggestion'
          WHEN page_type = 'pre_search' AND page_section[0] = 'hot_searches' THEN 'sdp_hot_search'
          WHEN page_type = 'pre_search' AND page_section[0] = 'search_bar' AND target_type = 'hint_keyword' AND input_type IS NULL THEN 'sdp_null'
          WHEN page_type = 'search_suggest_page' AND page_section[0] = 'search_bar' AND target_type = 'next_keyword' THEN 'sup_ymws'
          WHEN page_type = 'search_suggest_page' AND page_section[0] = 'search_bar' AND target_type = 'hint_keyword' AND input_type = 'shop' THEN 'sup_hint_history'
          WHEN page_type = 'search_suggest_page' AND page_section[0] = 'search_bar' AND target_type = 'hint_keyword' AND input_type = 'hint' THEN 'sup_auto_complete'
          WHEN page_type = 'search_suggest_page' AND page_section[0] = 'search_bar' AND target_type = 'hint_keyword' AND input_type = 'shop_history' THEN 'sup_shop_history'
          WHEN page_type = 'search_suggest_page' AND page_section[0] = 'search_bar' AND target_type = 'hint_keyword' AND input_type = 'history' THEN 'sup_hint_history'
          WHEN page_type = 'search_suggest_page' AND page_section[0] = 'search_bar' AND target_type = 'curated_search' THEN 'sup_curated_search'
          WHEN page_type = 'search' AND target_type = 'curated_search' THEN 'srp_curated_search'
          WHEN page_type = 'search' AND target_type = 'related_search' THEN 'srp_related_search'
    END AS mid
    ,concat_ws(',', collect_set(search_guide_request_id)) as search_guide_request_id
    ,max(operation) as operation
FROM srdi_mart.dwd_sr_data_warehouse_search
WHERE
    local_date = ${local_date}
  AND grass_region IN (${grass_region})
  AND page_type in ('pre_search', 'search_suggest_page', 'search')
  AND operation = 'click'
  AND user_id > 0
GROUP BY user_id, global_session_id, mid;


--sql_divide_splitter--
INSERT OVERWRITE TABLE ${schema}.dim_sr_data_warehouse_search_guide_request
PARTITION (
    grass_region = ${grass_region}
    ,local_date = ${local_date}
)
SELECT
     user_id
     ,global_session_id
     ,mid
     ,search_guide_request_id
     ,operation
FROM
    dim_search_guide_${grass_region_without_quote}
WHERE
    global_session_id IS NOT NULL;
